class Solution { public:
    int amountOfTime(TreeNode* root,int start) {
        unordered_map<int,vector<int>> g;
        queue<TreeNode*> nodes;nodes.push(root);
        while(!nodes.empty()){
            TreeNode* u=nodes.front();nodes.pop();
            if(u->left){g[u->val].push_back(u->left->val);g[u->left->val].push_back(u->val);nodes.push(u->left);}
            if(u->right){g[u->val].push_back(u->right->val);g[u->right->val].push_back(u->val);nodes.push(u->right);}
        }
        queue<int> q;q.push(start);unordered_set<int> seen={start};int minutes=-1;
        while(!q.empty()){int sz=q.size();++minutes;while(sz--){int u=q.front();q.pop();
            for(int v:g[u])if(seen.insert(v).second)q.push(v);
        }}
        return minutes;
    }
};
